Related Topic: Subarrays, Subsequences, and Subsets in Array

Approach(Using dynamic programming):

Initialize an array dp of size N, where dp[i] represents the maximum sum of a subsequence ending at the ith index.Initialize the dp array with the values of the original array.Iterate over the array from the Kth index to the end and for each index i, calculate dp[i] as the maximum value of dp[j] + arr[i], where j is the index that is K positions behind i.Return the maximum value in the dp array.Here is the  implementation of the above approach:



            C++

    #include <iostream>
#include <vector>
#include <algorithm>

int maxSubsequenceSum(std::vector<int>& arr, int K) {
    int N = arr.size();
    std::vector<int> dp = arr;
    for (int i = K; i < N; ++i) {
        for (int j = i - K; j >= i - K; j -= K) { // Corrected loop condition here
            if (j >= 0) {
                dp[i] = std::max(dp[i], dp[j] + arr[i]);
            }
        }
    }
    return *std::max_element(dp.begin(), dp.end());
}

int main() {
    std::vector<int> arr = {2, -3, -1, -1, 2};
    int K = 2;
    std::cout << maxSubsequenceSum(arr, K) << std::endl; // Output: 3
    return 0;
}


            Java

    import java.util.Arrays;

public class Main {
    // Function to find the maximum subsequence sum with a
    // constraint
    public static int maxSubsequenceSum(int[] arr, int K)
    {
        int N = arr.length;
        int[] dp = Arrays.copyOf(
            arr,
            N); // Initialize a dynamic programming array

        // Iterate through the elements
        for (int i = K; i < N; ++i) {
            // Find the maximum sum considering the
            // constraint
            for (int j = i - K; j >= i - K && j >= 0;
                 j -= K) {
                dp[i] = Math.max(dp[i], dp[j] + arr[i]);
            }
        }

        // Find and return the maximum value in the dynamic
        // programming array
        int max = Arrays.stream(dp).max().getAsInt();
        return max;
    }

    public static void main(String[] args)
    {
        int[] arr = { 2, -3, -1, -1, 2 };
        int K = 2;
        System.out.println(
            maxSubsequenceSum(arr, K)); // Output: 3
    }
}


